static uint16_t rd16(const uint8_t*p){return uint16_t(p[0])|uint16_t(p[1])<<8;}
static uint32_t rd32(const uint8_t*p){return uint32_t(p[0])|uint32_t(p[1])<<8|uint32_t(p[2])<<16|uint32_t(p[3])<<24;}
static uint64_t rd64(const uint8_t*p){return uint64_t(rd32(p))|uint64_t(rd32(p+4))<<32;}
struct ZipEntry { std::string name; uint32_t method=0, csize=0, usize=0, local=0; };
struct ZipFile {
  fs::path path; uint64_t file_size=0; std::map<std::string,ZipEntry> entries;
  explicit ZipFile(const fs::path&p):path(p){std::ifstream f(path,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("cannot open "+p.string());auto n=f.tellg();if(n<0||uint64_t(n)>(1ull<<32))throw std::runtime_error(".pt file too large (>4 GiB unsupported)");file_size=(uint64_t)n;parse(f);}
  static void read_at(std::ifstream&f,uint64_t off,void*out,size_t n){f.seekg((std::streamoff)off);if(!f.read((char*)out,(std::streamsize)n))throw std::runtime_error("truncated .pt ZIP");}
  void parse(std::ifstream&f){if(file_size<22)throw std::runtime_error("invalid .pt ZIP");size_t tailn=(size_t)std::min<uint64_t>(file_size,65557);std::vector<uint8_t> tail(tailn);read_at(f,file_size-tailn,tail.data(),tail.size());size_t eocd=SIZE_MAX;for(size_t q=tail.size()-22;;--q){if(rd32(tail.data()+q)==0x06054b50u){eocd=q;break;}if(q==0)break;}if(eocd==SIZE_MAX)throw std::runtime_error("missing ZIP central directory");uint16_t n=rd16(tail.data()+eocd+10);uint32_t cdsize=rd32(tail.data()+eocd+12), cdoff=rd32(tail.data()+eocd+16);if(n>65535||cdsize>(256u<<20)||uint64_t(cdoff)+cdsize>file_size)throw std::runtime_error("bad ZIP central directory");std::vector<uint8_t> cd(cdsize);read_at(f,cdoff,cd.data(),cd.size());size_t q=0;for(uint16_t i=0;i<n;++i){if(q+46>cd.size()||rd32(cd.data()+q)!=0x02014b50u)throw std::runtime_error("bad ZIP entry");ZipEntry e;e.method=rd16(cd.data()+q+10);e.csize=rd32(cd.data()+q+20);e.usize=rd32(cd.data()+q+24);uint16_t nl=rd16(cd.data()+q+28),xl=rd16(cd.data()+q+30),cl=rd16(cd.data()+q+32);e.local=rd32(cd.data()+q+42);if(q+46ull+nl+xl+cl>cd.size()||nl>4096)throw std::runtime_error("truncated/oversized ZIP entry");e.name.assign((char*)cd.data()+q+46,nl);entries.emplace(e.name,e);q+=46+nl+xl+cl;}}
  uint64_t size(const std::string&name)const{auto it=entries.find(name);if(it==entries.end())throw std::runtime_error("missing .pt member: "+name);return it->second.usize;}
  std::vector<uint8_t> get(const std::string&name)const{auto it=entries.find(name);if(it==entries.end())throw std::runtime_error("missing .pt member: "+name);auto&e=it->second;if(e.method!=0)throw std::runtime_error("compressed .pt members are unsupported");std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("cannot reopen "+path.string());uint8_t h[30];read_at(f,e.local,h,sizeof h);if(rd32(h)!=0x04034b50u)throw std::runtime_error("bad local ZIP entry");uint16_t nl=rd16(h+26),xl=rd16(h+28);uint64_t d=uint64_t(e.local)+30+nl+xl;if(d+e.usize>file_size)throw std::runtime_error("truncated .pt member");std::vector<uint8_t> out(e.usize);if(e.usize)read_at(f,d,out.data(),out.size());return out;}
};
struct Global{std::string module,name;}; struct Storage{std::string key,dtype;int64_t size=0;}; struct Tensor{Storage storage;int64_t offset=0;std::vector<int64_t> shape,stride;};
struct Value { using List=std::vector<Value>; using Dict=std::map<std::string,Value>; std::variant<std::monostate,bool,int64_t,double,std::string,List,Dict,Global,Storage,Tensor> v; Value()=default; template<class T>Value(T x):v(std::move(x)){} };
struct Mark{};
class Pickle {
 const std::vector<uint8_t>&b;size_t p=0;std::vector<std::variant<Value,Mark>> st;std::map<uint32_t,Value> memo;
 uint8_t u8(){if(p>=b.size())throw std::runtime_error("truncated pickle");return b[p++];} uint16_t u16(){if(p+2>b.size())throw std::runtime_error("truncated pickle");auto x=rd16(b.data()+p);p+=2;return x;} uint32_t u32(){if(p+4>b.size())throw std::runtime_error("truncated pickle");auto x=rd32(b.data()+p);p+=4;return x;}
 std::string take(size_t n){if(n>(1u<<20))throw std::runtime_error("pickle string too large");if(p+n>b.size())throw std::runtime_error("truncated pickle string");std::string s((char*)b.data()+p,n);p+=n;return s;} std::string line(){size_t q=p;while(q<b.size()&&b[q]!='\n')++q;if(q==b.size())throw std::runtime_error("bad pickle line");std::string s((char*)b.data()+p,q-p);p=q+1;return s;}
 Value popv(){if(st.empty()||!std::holds_alternative<Value>(st.back()))throw std::runtime_error("pickle stack error");Value v=std::get<Value>(std::move(st.back()));st.pop_back();return v;} size_t mark(){for(size_t i=st.size();i-->0;)if(std::holds_alternative<Mark>(st[i]))return i;throw std::runtime_error("pickle MARK missing");}
 static int64_t asint(const Value&v){if(auto*x=std::get_if<int64_t>(&v.v))return*x;throw std::runtime_error("pickle integer expected");} static std::string asstr(const Value&v){if(auto*x=std::get_if<std::string>(&v.v))return*x;throw std::runtime_error("pickle string expected");}
 static Value::List aslist(const Value&v){if(auto*x=std::get_if<Value::List>(&v.v))return*x;throw std::runtime_error("pickle tuple/list expected");}
 void reduce(){Value args=popv(), fn=popv();auto*g=std::get_if<Global>(&fn.v);if(!g)throw std::runtime_error("unsafe pickle REDUCE callable");auto a=aslist(args);if(g->module=="collections"&&g->name=="OrderedDict"){if(!a.empty())throw std::runtime_error("unsupported OrderedDict args");st.emplace_back(Value(Value::Dict{}));return;}if(g->module=="torch._utils"&&(g->name=="_rebuild_tensor_v2"||g->name=="_rebuild_tensor")){if(a.size()<4)throw std::runtime_error("bad tensor rebuild");auto*s=std::get_if<Storage>(&a[0].v);if(!s)throw std::runtime_error("bad tensor storage");Tensor t;t.storage=*s;t.offset=asint(a[1]);for(auto&x:aslist(a[2]))t.shape.push_back(asint(x));for(auto&x:aslist(a[3]))t.stride.push_back(asint(x));st.emplace_back(Value(t));return;}throw std::runtime_error("unsupported/unsafe pickle global: "+g->module+"."+g->name);}
 public: explicit Pickle(const std::vector<uint8_t>&x):b(x){} Value run(){for(;;){uint8_t op=u8();switch(op){case 0x80:u8();break;case 0x95:p+=8;if(p>b.size())throw std::runtime_error("bad pickle frame");break;case '}':st.emplace_back(Value(Value::Dict{}));break;case ']':st.emplace_back(Value(Value::List{}));break;case ')':st.emplace_back(Value(Value::List{}));break;case '(' :st.emplace_back(Mark{});break;case 'N':st.emplace_back(Value{});break;case 0x88:st.emplace_back(Value(true));break;case 0x89:st.emplace_back(Value(false));break;case 'K':st.emplace_back(Value((int64_t)u8()));break;case 'M':st.emplace_back(Value((int64_t)u16()));break;case 'J':{int32_t x=(int32_t)u32();st.emplace_back(Value((int64_t)x));break;}case 0x8a:{uint8_t n=u8();if(n>8)throw std::runtime_error("pickle integer too large");uint64_t x=0;for(unsigned i=0;i<n;++i)x|=uint64_t(u8())<<(8*i);st.emplace_back(Value((int64_t)x));break;}case 'G':{if(p+8>b.size())throw std::runtime_error("truncated float");uint64_t u=0;for(int i=0;i<8;++i)u=(u<<8)|b[p++];double d;std::memcpy(&d,&u,8);st.emplace_back(Value(d));break;}case 'X':{uint32_t n=u32();st.emplace_back(Value(take(n)));break;}case 0x8c:{uint8_t n=u8();st.emplace_back(Value(take(n)));break;}case 'c':st.emplace_back(Value(Global{line(),line()}));break;case 0x93:{auto name=asstr(popv()),mod=asstr(popv());st.emplace_back(Value(Global{mod,name}));break;}case 'q':memo[u8()]=std::get<Value>(st.back());break;case 'r':memo[u32()]=std::get<Value>(st.back());break;case 0x94:memo[(uint32_t)memo.size()]=std::get<Value>(st.back());break;case 'h':{auto i=u8();if(!memo.count(i))throw std::runtime_error("bad pickle memo");st.emplace_back(memo[i]);break;}case 'j':{auto i=u32();if(!memo.count(i))throw std::runtime_error("bad pickle memo");st.emplace_back(memo[i]);break;}case 'Q':{Value id=popv();auto a=aslist(id);if(a.size()!=5||asstr(a[0])!="storage")throw std::runtime_error("unsupported pickle persistent id");auto*g=std::get_if<Global>(&a[1].v);if(!g||g->module!="torch")throw std::runtime_error("bad storage type");std::string dt;if(g->name=="FloatStorage")dt="F32";else if(g->name=="HalfStorage")dt="F16";else if(g->name=="BFloat16Storage")dt="BF16";else if(g->name=="IntStorage")dt="I32";else if(g->name=="LongStorage")dt="I64";else throw std::runtime_error("unsupported storage type: "+g->name);st.emplace_back(Value(Storage{asstr(a[2]),dt,asint(a[4])}));break;}case 0x85:{Value a=popv();st.emplace_back(Value(Value::List{a}));break;}case 0x86:{Value b2=popv(),a=popv();st.emplace_back(Value(Value::List{a,b2}));break;}case 0x87:{Value c=popv(),b2=popv(),a=popv();st.emplace_back(Value(Value::List{a,b2,c}));break;}case 't':{size_t m=mark();Value::List a;for(size_t i=m+1;i<st.size();++i)a.push_back(std::get<Value>(st[i]));st.resize(m);st.emplace_back(Value(a));break;}case 'e':{size_t m=mark();Value vals=std::get<Value>(st[m-1]);auto*l=std::get_if<Value::List>(&vals.v);if(!l)throw std::runtime_error("APPENDS target not list");for(size_t i=m+1;i<st.size();++i)l->push_back(std::get<Value>(st[i]));st.resize(m-1);st.emplace_back(vals);break;}case 'a':{Value x=popv(),vals=popv();auto*l=std::get_if<Value::List>(&vals.v);if(!l)throw std::runtime_error("APPEND target not list");l->push_back(x);st.emplace_back(vals);break;}case 's':{Value val=popv(),key=popv(),d=popv();auto*o=std::get_if<Value::Dict>(&d.v);if(!o)throw std::runtime_error("SETITEM target not dict");(*o)[asstr(key)]=val;st.emplace_back(d);break;}case 'u':{size_t m=mark();if(m==0)throw std::runtime_error("bad SETITEMS");Value d=std::get<Value>(st[m-1]);auto*o=std::get_if<Value::Dict>(&d.v);if(!o||(st.size()-m-1)%2)throw std::runtime_error("bad SETITEMS target");for(size_t i=m+1;i<st.size();i+=2)(*o)[asstr(std::get<Value>(st[i]))]=std::get<Value>(st[i+1]);st.resize(m-1);st.emplace_back(d);break;}case 'R':reduce();break;case 'b':{Value state=popv();Value obj=popv();(void)state;st.emplace_back(obj);break;}case '.':return popv();default:throw std::runtime_error("unsupported pickle opcode 0x"+[] (uint8_t x){const char*h="0123456789abcdef";std::string s;s+=h[x>>4];s+=h[x&15];return s;}(op));}}}
};
inline bool contiguous(const std::vector<int64_t>&shape,const std::vector<int64_t>&stride){if(shape.size()!=stride.size())return false;int64_t s=1;for(size_t i=shape.size();i-->0;){if(stride[i]!=s)return false;s*=shape[i];}return true;}
struct Checkpoint { Value config; std::map<std::string,Tensor> tensors; std::string prefix; ZipFile zip; explicit Checkpoint(const fs::path&p):zip(p){std::string dp;for(auto&kv:zip.entries)if(kv.first.size()>=8&&kv.first.substr(kv.first.size()-8)=="data.pkl"){dp=kv.first;break;}if(dp.empty())throw std::runtime_error("model.pt has no data.pkl");prefix=dp.substr(0,dp.size()-8);if(zip.size(dp)>(256u<<20))throw std::runtime_error("data.pkl too large");Value root=Pickle(zip.get(dp)).run();auto*d=std::get_if<Value::Dict>(&root.v);if(!d)throw std::runtime_error("checkpoint root is not dict");auto ci=d->find("model_config"),mi=d->find("model");if(ci==d->end()||mi==d->end())throw std::runtime_error("checkpoint must contain model_config and model");config=ci->second;auto*md=std::get_if<Value::Dict>(&mi->second.v);if(!md)throw std::runtime_error("checkpoint model is not a state_dict");for(auto&kv:*md){auto*t=std::get_if<Tensor>(&kv.second.v);if(!t)throw std::runtime_error("non-tensor in model state_dict: "+kv.first);if(!contiguous(t->shape,t->stride))throw std::runtime_error("non-contiguous tensor unsupported: "+kv.first);tensors.emplace(kv.first,*t);}}
 std::vector<uint8_t> storage(const Storage&s)const{return zip.get(prefix+"data/"+s.key);} };
